import {analyze,ranking,SERVICE} from './analysis.mjs';
const $=id=>document.getElementById(id),fmt=(v,n=1)=>new Intl.NumberFormat('pt-BR',{maximumFractionDigits:n,minimumFractionDigits:n}).format(v);let data,type='positive',busy=false;
const map=L.map('map',{worldCopyJump:true,minZoom:2,maxZoom:15}).setView([-16.758611,-49.344444],7);
L.tileLayer('https://tile.openstreetmap.org/{z}/{x}/{y}.png',{attribution:'&copy; <a href="https://www.openstreetmap.org/copyright">OpenStreetMap</a> contributors',maxZoom:19,referrerPolicy:'strict-origin-when-cross-origin'}).addTo(map);
const Magnetic=L.TileLayer.extend({getTileUrl(coords){const size=this.getTileSize(),nw=map.unproject(coords.scaleBy(size),coords.z),se=map.unproject(coords.add(L.point(1,1)).scaleBy(size),coords.z);return SERVICE+'/exportImage?'+new URLSearchParams({bbox:[nw.lng,se.lat,se.lng,nw.lat].join(','),bboxSR:'4326',imageSR:'3857',size:'256,256',format:'png32',transparent:'true',renderingRule:JSON.stringify({rasterFunction:'EMAG2_Color_Scale'}),f:'image'});}});
const magnetic=new Magnetic('',{opacity:.65,attribution:'NOAA/NCEI EMAG2 v3',maxZoom:15}).addTo(map);let layerWarned=false;magnetic.on('tileerror',()=>{if(!layerWarned){layerWarned=true;status('A camada global está temporariamente indisponível. A análise numérica continua independente.',true);}});
const markers=L.layerGroup().addTo(map);let circle,center;function status(text,error=false){$('status').textContent=text;$('status').classList.toggle('error',error);}function selected(lat,lon){$('lat').value=lat.toFixed(6);$('lon').value=lon.toFixed(6);if(center)center.remove();center=L.circleMarker([lat,lon],{radius:7,color:'#fff',weight:3,fillColor:'#101b2b',fillOpacity:1}).addTo(map);}
map.on('click',e=>{if(busy)return;const lon=((e.latlng.lng+180)%360+360)%360-180;selected(Math.max(-85,Math.min(85,e.latlng.lat)),lon);status('Ponto selecionado. Clique em “Analisar região” para atualizar os resultados.');});$('overlay').onchange=()=>{$('overlay').checked?magnetic.addTo(map):magnetic.remove();};
function popup(p,i){return `<b>Ponto ${i+1}</b><br>${fmt(p.lat,5)}, ${fmt(p.lon,5)}<br>Anomalia: <b>${fmt(p.value)} nT</b><br>Distância: ${fmt(p.km)} km<br>Gradiente: ${Number.isFinite(p.gradient)?fmt(p.gradient)+' nT/km':'indisponível'}`;}
function renderRanking(){markers.clearLayers();$('rows').replaceChildren();const list=ranking(data,type);for(const [i,p] of list.entries()){const marker=L.marker([p.lat,p.lon],{icon:L.divIcon({className:'',html:`<div class="marker">${i+1}</div>`,iconSize:[28,28],iconAnchor:[14,14]})}).addTo(markers).bindPopup(popup(p,i));const tr=document.createElement('tr');tr.innerHTML=`<td>${String(i+1).padStart(2,'0')}</td><td>${fmt(p.lat,5)}, ${fmt(p.lon,5)}</td><td>${fmt(p.km)} km</td><td>${fmt(p.value)} nT</td><td>${Number.isFinite(p.gradient)?fmt(p.gradient)+' nT/km':'—'}</td><td><button aria-label="Ver ponto ${i+1} no mapa">Ver ↗</button></td>`;tr.querySelector('button').onclick=()=>{map.setView([p.lat,p.lon],10);marker.openPopup();$('map').scrollIntoView({behavior:'smooth',block:'center'});};$('rows').append(tr);}if(!list.length)$('rows').innerHTML='<tr><td colspan="6">Nenhum ponto disponível nesta categoria.</td></tr>';}
function render(){selected(data.lat,data.lon);if(circle)circle.remove();circle=L.circle([data.lat,data.lon],{radius:data.radius*1000,color:'#183f49',weight:1.5,dashArray:'6 5',fillOpacity:.025}).addTo(map);map.fitBounds(circle.getBounds(),{padding:[15,15]});const values=data.points.map(p=>p.value);$('min').textContent=fmt(Math.min(...values))+' nT';$('max').textContent=fmt(Math.max(...values))+' nT';$('count').textContent=fmt(values.length,0);$('range').textContent=data.radius+' km';$('context').textContent=`Centro: ${fmt(data.lat,5)}, ${fmt(data.lon,5)} · ${fmt(values.length/data.total*100)}% das células com dados · Consulta ${new Date(data.date).toLocaleDateString('pt-BR')}`;$('download').disabled=false;renderRanking();}
async function run(useCache=false){if(busy)return;busy=true;$('analyze').disabled=true;$('locate').disabled=true;$('home').disabled=true;$('progress').hidden=false;$('progress').value=0;const lat=Number($('lat').value),lon=Number($('lon').value),radius=Number($('radius').value);try{if(!Number.isFinite(lat)||Math.abs(lat)>85||!Number.isFinite(lon)||Math.abs(lon)>180)throw Error('Informe latitude entre −85 e 85 e longitude entre −180 e 180.');status('Consultando a grade magnética oficial…');let cached;if(useCache){try{const r=await fetch('goiania.json');if(r.ok)cached=await r.json();}catch{}}data=cached??await analyze(lat,lon,radius,p=>{$('progress').value=p;status(`Consultando a NOAA: ${Math.round(p*100)}% concluído…`);});render();status(`Análise concluída. ${data.points.length} células válidas no raio de ${data.radius} km.${cached?' Dados de Goiânia salvos para abertura rápida.':''}`);}catch(e){status('Não foi possível concluir: '+e.message+(data?' Os resultados anteriores foram mantidos.':' Tente novamente em alguns instantes.'),true);}finally{busy=false;$('analyze').disabled=false;$('locate').disabled=false;$('home').disabled=false;$('progress').hidden=true;}}
$('search').onsubmit=e=>{e.preventDefault();run();};$('home').onclick=()=>{selected(-16.758611,-49.344444);$('radius').value='100';run(true);};$('locate').onclick=()=>{if(!navigator.geolocation){status('Este navegador não oferece localização.',true);return;}status('Obtendo sua localização…');navigator.geolocation.getCurrentPosition(p=>{selected(p.coords.latitude,p.coords.longitude);map.setView([p.coords.latitude,p.coords.longitude],8);status('Localização selecionada. Clique em “Analisar região”.');},()=>status('Não foi possível obter a localização. Você pode clicar no mapa ou informar coordenadas.',true),{timeout:15000});};
document.querySelectorAll('[data-type]').forEach(b=>b.onclick=()=>{type=b.dataset.type;document.querySelectorAll('[data-type]').forEach(el=>{el.classList.toggle('active',el===b);el.setAttribute('aria-pressed',String(el===b));});if(data)renderRanking();});
$('download').onclick=()=>{const rows=[['fonte','consulta_utc','centro_lat','centro_lon','raio_km','latitude','longitude','distancia_km','anomalia_nT','gradiente_nT_km'],...data.points.map(p=>['NOAA EMAG2 v3',data.date,data.lat,data.lon,data.radius,p.lat,p.lon,p.km,p.value,p.gradient??''])];const blob=new Blob(['\uFEFF'+rows.map(r=>r.join(';')).join('\r\n')],{type:'text/csv;charset=utf-8'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='magneterra-analise.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};
run(true);
